package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	node := maelstrom.NewNode()
	kv := maelstrom.NewLinKV(node)

	node.Handle("append", func(msg maelstrom.Message) error {
		var body struct {
			maelstrom.MessageBody
			Journal string `json:"journal"`
			Entry   int    `json:"entry"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		pos, err := appendToJournal(context.Background(), kv, body.Journal, body.Entry)
		if err != nil {
			return err
		}

		return node.Reply(msg, map[string]any{
			"type":       "appended",
			"position":   pos,
		})
	})

	node.Handle("fetch", func(msg maelstrom.Message) error {
		var body struct {
			maelstrom.MessageBody
			Positions map[string]int `json:"positions"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		result := make(map[string][][2]int)
		for journal, start := range body.Positions {
			arr, err := readJournal(context.Background(), kv, journal)
			if err != nil {
				return err
			}
			if arr == nil {
				continue
			}
			if start < 0 {
				start = 0
			}
			if start >= len(arr) {
				continue
			}
			maxEntries := 100
			end := start + maxEntries
			if end > len(arr) {
				end = len(arr)
			}
			pairs := make([][2]int, 0, end-start)
			for i := start; i < end; i++ {
				entry, ok := arr[i].(int)
				if !ok {
					switch v := arr[i].(type) {
					case float64:
						entry = int(v)
					case int:
						entry = v
					default:
						entry = 0
					}
				}
				pairs = append(pairs, [2]int{i, entry})
			}
			if len(pairs) > 0 {
				// Convert to format expected: array of [position, entry]
				converted := make([]any, len(pairs))
				for i, p := range pairs {
					converted[i] = []any{p[0], p[1]}
				}
				result[journal] = converted // Wait, result is map[string][][2]int. Let's adjust.
			}
		}

		// Let's rebuild result correctly
		result2 := make(map[string]any)
		for journal, pairs := range result {
			if len(pairs) > 0 {
				converted := make([]any, len(pairs))
				for i, p := range pairs {
					converted[i] = []any{p[0], p[1]}
				}
				result2[journal] = converted
			}
		}

		return node.Reply(msg, map[string]any{
			"type":     "fetched",
			"entries": result2,
		})
	})

	node.Handle("bookmark", func(msg maelstrom.Message) error {
		var body struct {
			maelstrom.MessageBody
			Positions map[string]int `json:"positions"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		for journal, pos := range body.Positions {
			if err := kv.Write(context.Background(), "bookmark:"+journal, pos); err != nil {
				return err
			}
		}

		return node.Reply(msg, map[string]any{
			"type": "bookmarked",
		})
	})

	node.Handle("bookmarks", func(msg maelstrom.Message) error {
		var body struct {
			maelstrom.MessageBody
			Journals []string `json:"journals"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		result := make(map[string]int)
		for _, journal := range body.Journals {
			v, err := kv.Read(context.Background(), "bookmark:"+journal)
			if err != nil {
				var rpcErr *maelstrom.RPCError
				if errors.As(err, &rpcErr) && rpcErr.Code == maelstrom.KeyDoesNotExist {
					continue
				}
				return err
			}
			switch val := v.(type) {
			case float64:
				result[journal] = int(val)
			case int:
				result[journal] = val
			default:
				result[journal] = 0
			}
		}

		return node.Reply(msg, map[string]any{
			"type":      "bookmarks_are",
			"positions": result,
		})
	})

	if err := node.Run(); err != nil {
		log.Fatalf("node error: %v", err)
